                  "మంచి సమావేశం నమ్మకాన్ని పెంచుతుంది. రైతులు తమ మాట వినబడుతోందని భావించినప్పుడు, వారు MPP ని ఎక్కువగా నమ్ముతారు — వేరే వారికి అమ్మే బదులు తమ పాలను అక్కడికే తీసుకువస్తూనే ఉంటారు.",
